"""Explain atomic clearing, XOR waiter flags and instrumentation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1381': ('전등 여러 개가 붙은 판에서 잠금 전등 하나만 끄려 합니다. 다른 전등까지 전부 끄면 다른 사람이 남긴 표시를 잃게 됩니다.', '원자적 AND NOT이 선택한 비트만 지우는 방법을 이해합니다.', '값 1011에서 0번 비트만 지우세요. 마스크는 0001, 네 칸에서 반전한 마스크는 1110입니다. 1011 AND 1110은 1010입니다.', ['arch_clear_bit_unlock은 비트 잠금을 푸는 공통 구현입니다. nr은 지울 비트 번호입니다. BIT_WORD(nr)로 그 비트가 들어 있는 unsigned long 원소까지 포인터를 이동합니다. word는 비트를 담은 정수 한 묶음입니다.', 'BIT_MASK(nr)은 그 word 안에서 대상 비트만 1인 값을 만듭니다. andnot은 마스크를 반전한 값과 AND한다는 뜻입니다. 대상 위치에는 0을, 다른 위치에는 1을 AND하므로 대상만 지워집니다.', '네 칸 예시로 1011에서 mask=0001이면 결과는 1010입니다. 높은 세 칸은 그대로입니다. 실제 word는 32비트나 64비트지만 같은 계산 원리가 적용됩니다. word 전체를 0으로 만드는 초기화와 다릅니다.', 'raw_atomic_long_fetch_andnot_release는 읽고 바꾸는 전체를 하나의 원자적 변경으로 처리합니다. 다른 비트의 독립적인 원자적 변경이 먼저 일어났다면 그 갱신을 포함한 값에서 대상 비트만 지웁니다. 옛 복사본을 나중에 통째로 덮어쓰는 방식과 다릅니다.', 'release는 잠금 안에서 먼저 한 데이터 접근과 잠금 해제 사이의 순서 약속입니다. 다음 사용자가 같은 잠금을 대응하는 acquire 방식으로 얻는 흐름과 함께 보호 데이터를 전달하는 데 사용합니다.', '이 약속이 아무 주소를 한 번 읽는 동작과 자동으로 연결되는 것은 아닙니다. 관계없는 잠금을 읽거나 잠금 없이 데이터에 접근하는 것으로 대체하면 안 됩니다. 객체가 살아 있고 같은 보호 규칙을 따르는 조건도 여전히 필요합니다.'], [('이 함수는 잠금 비트를 어떤 계산으로 지울까요?', ['word 전체를 무조건 0으로 써요', '마스크를 반전한 값과 AND해요'], '마스크의 대상 위치는 반전하면 0, 나머지는 1입니다. AND하면 대상만 0이 되고 나머지 비트는 보존됩니다. 예를 들어 1011에서 0번만 지우면 1010입니다.'), ('release로 풀면 관계없는 잠금을 읽어도 데이터 전달 순서가 자동으로 맞을까요?', ['아니요. 대응하는 acquire 사용 규칙이 필요해요', '네. 어떤 조회든 모두 자동으로 맞아요'], 'release는 올바른 동기화 관계 안에서 해석해야 합니다. 같은 잠금을 올바르게 얻는 흐름이 필요하며, 관계없는 주소의 조회가 그 역할을 대신하지 않습니다.')]), 'os1382': ('사진 한 장을 온전히 찍고 수정한 사진을 온전히 붙여도, 두 일 사이에 원본이 바뀔 수 있습니다. 각 단계가 안전하다는 말과 전체가 한 동작이라는 말은 다릅니다.', '분리된 읽기와 저장이 원자적 읽기·수정·쓰기와 다른 이유를 배웁니다.', '처음 0101을 읽어 보관하세요. 다른 실행 흐름이 3번을 켜 실제 값은 1101이 됩니다. 옛 값에서 0번을 지운 0100을 저장하면 새 3번이 사라집니다.', ['arch___clear_bit_unlock은 약한 해제의 공통 구현입니다. 먼저 BIT_WORD로 해당 word를 찾습니다. 그런 다음 READ_ONCE(*p)로 읽은 word 전체를 old라는 지역 변수에 보관합니다.', 'old &= ~BIT_MASK(nr)은 그 복사본의 잠금 비트만 지웁니다. 이 줄만으로 실제 메모리가 바뀌는 것은 아닙니다. old라는 숫자를 계산한 뒤 다음 저장 단계에서 메모리에 반영합니다.', 'raw_atomic_long_set_release는 계산한 old 전체를 저장합니다. 저장 폭은 unsigned long 한 word입니다. 선택한 비트를 독립된 한 바이트로 골라 저장하는 방식이 아닙니다.', '0101을 읽은 뒤 다른 CPU가 3번을 켜서 1101로 만들었다고 합시다. 옛 복사본 0101의 0번을 지우면 0100입니다. 이것을 저장하면 다른 CPU가 켠 3번이 사라집니다. 최신 값 1101에서 지웠다면 1100이어야 합니다.', '각 읽기나 저장이 찢어지지 않는다는 조건이 있어도 둘 사이에 다른 실행이 끼어들 수 있습니다. 따라서 두 단계를 합친 전체를 원자적 읽기·수정·쓰기라고 할 수 없습니다. release라는 순서 약속도 이 간격을 없애 주지는 않습니다.', '다른 CPU가 같은 word의 다른 비트를 동시에 바꾸지 않는다는 조건에서 이 해제를 사용해야 합니다. 예를 들어 나머지 상태 비트 수정도 같은 잠금으로 보호할 수 있습니다. 함수 이름의 atomic이나 release라는 일부 단어만 보고 전체 사용 조건을 판단하지 마세요.'], [('읽기와 저장이 각각 원자적이면 두 단계 전체도 자동으로 원자적일까요?', ['네. 각각 원자적이면 전체도 한 동작이에요', '아니요. 두 단계 사이에 다른 수정이 들어올 수 있어요'], '사진을 찍은 뒤 붙이기 전에 원본이 바뀔 수 있는 것과 같습니다. 둘 사이의 간격이 있으므로 옛 값으로 저장하면 새 변경을 잃을 수 있습니다.'), ('약한 공통 구현은 계산한 값을 어느 크기로 저장할까요?', ['unsigned long 한 word 전체로 저장해요', '선택 비트 하나를 별도 바이트로 저장해요'], 'old는 word 전체를 담고 set_release가 그 값을 통째로 씁니다. 이것이 다른 비트의 최신 변경까지 덮어쓸 수 있는 이유입니다.')]), 'os1383': ('작업 중 표시를 바꾸면서 기다리는 사람이 있는지도 확인합니다. 바꿀 표시와 기다림 표시는 서로 다른 칸에 있습니다.', 'XOR로 바꾸는 비트와 반환값으로 확인하는 이전 비트를 구별합니다.', '이전 값 10000001과 마스크 00000001을 XOR하세요. 결과는 10000000이고 이전 7번 비트가 1이어서 반환은 참입니다. 마스크에 7번을 넣지 마세요.', ['XOR는 마스크가 1인 자리의 값을 뒤집습니다. 원래 1이면 0, 원래 0이면 1이 됩니다. 따라서 언제나 지우는 AND NOT과 다릅니다. 이 해제 함수를 쓰는 상위 코드는 뒤집을 상태가 올바른지 알고 있어야 합니다.', 'arch_xor_unlock_is_negative_byte의 공통 구현은 raw_atomic_long_fetch_xor_release로 word를 바꿉니다. fetch는 바꾸기 전 word를 old에 돌려준다는 뜻입니다. 그다음 반환값은 !!(old & BIT(7))로 계산합니다.', 'BIT(7)은 낮은 바이트의 가장 높은 비트입니다. 바이트는 8비트이고 번호는 0부터 7입니다. 64비트 long 전체의 가장 높은 63번을 검사하는 것이 아닙니다. 함수 이름의 negative byte를 word 전체의 음수 검사라고 읽으면 안 됩니다.', '공개 함수의 문서는 바꾸는 마스크를 낮은 바이트의 0~6번 비트에 사용하는 것으로 설명합니다. 7번은 PG_waiters, 즉 잠금 해제를 기다리는 사람이 있는지 나타내는 표시입니다. 이 프로토콜에서 7번을 임의로 뒤집지 않습니다.', '이전 값이 10000001이고 마스크가 00000001이면 새 값은 10000000입니다. 반환은 이전 7번이 1이라 참입니다. 이전 값 00000001이면 새 값은 00000000이고 반환은 거짓입니다. 반환이 새 word 전체 숫자는 아닙니다.', 'folio는 메모리 페이지 하나 이상을 묶어 다루는 커널 객체입니다. 이 기술은 folio 잠금 해제나 저장 작업 완료와 함께 상태를 바꾸고 대기 여부를 확인하는 데 쓰입니다. 여기서는 같은 원자적 변경에서 얻은 이전 7번을 확인한다는 점과 허용된 마스크 범위를 함께 기억하세요.'], [('공통 구현이 반환값을 만들 때 확인하는 비트는 무엇일까요?', ['long 전체의 63번 비트예요', '바꾸기 전 word의 7번 비트예요'], '코드가 old & BIT(7)을 계산합니다. old는 변경 전 값이고 7번은 낮은 바이트의 맨 위 비트입니다. long 전체의 최고 비트와 다릅니다.'), ('공개 문서가 마스크로 바꾸도록 설명하는 범위는 어디일까요?', ['낮은 바이트의 0~6번이에요', 'word의 모든 비트를 마음대로 바꿔요'], '7번은 기다리는 사람이 있는지 나타내는 별도 표시입니다. 공통 XOR 식이 계산할 수 있는 범위와 공개 함수가 약속한 사용 범위는 구별해야 합니다.')]), 'os1384': ('작업자가 일하기 전에 관찰자에게 어디를 어떻게 고칠지 알려 줄 수 있습니다. 알려 주는 일과 실제로 고치는 일은 서로 다른 단계입니다.', '분석 도구용 접근 표시와 실제 잠금 연산을 구별합니다.', '64비트 word에서 nr=65이면 두 번째 word를 가리키고 접근 크기는 8바이트라고 적으세요. 접근 알림 → 실제 arch 함수 호출 순서로 화살표를 그리세요.', ['instrumented-lock.h는 잠금 연산을 감싼 함수들을 제공합니다. instrumentation은 분석 도구가 동작을 살펴볼 수 있도록 정보를 붙이는 것입니다. 이 함수들은 어떤 메모리 접근을 하는지 알린 뒤 실제 구현을 부릅니다.', 'test_and_set_bit_lock은 instrument_atomic_read_write를 먼저 호출합니다. 원자적 읽기·쓰기 접근임을 알리는 표시입니다. 위치는 addr + BIT_WORD(nr), 크기는 sizeof(long)입니다. 주소의 덧셈은 바이트 번호가 아니라 word 원소만큼 이동합니다.', '64비트 word에서 nr=65이면 BIT_WORD는 1이므로 두 번째 word를 가리킵니다. sizeof(long)은 이 환경에서 8바이트입니다. 비트 번호 65를 주소에 65바이트 더하는 것으로 읽으면 틀립니다. 실제 비트 선택은 이어지는 arch 함수가 처리합니다.', '일반 clear_bit_unlock은 kcsan_release로 분석 도구에 release를 알리고 instrument_atomic_write를 호출합니다. 약한 __clear_bit_unlock은 대신 instrument_write를 씁니다. 약한 연산의 읽기·수정·쓰기 전체가 원자적이지 않다는 사용 계약을 구별하는 표시입니다.', 'XOR 해제도 kcsan_release와 instrument_atomic_write를 거쳐 arch_xor_unlock_is_negative_byte를 부릅니다. 이런 알림만으로 실제 잠금 비트가 바뀌는 것은 아닙니다. 각 arch 함수가 실제 변경과 필요한 메모리 순서를 구현합니다.', 'KCSAN은 커널의 동시 접근 문제를 찾는 분석 도구입니다. 접근 알림이 있다고 잘못된 주소나 모든 경쟁 문제가 저절로 해결되는 것은 아닙니다. 호출자는 유효한 비트 번호와 공간을 준비하고 잠금 규칙을 지켜야 합니다.'], [('약한 __clear_bit_unlock은 어떤 접근 알림을 사용할까요?', ['항상 instrument_atomic_read_write를 사용해요', 'instrument_write를 사용해요'], '원문은 약한 clear에 일반 쓰기 알림 instrument_write를 사용합니다. test_and_set_bit_lock의 원자적 읽기·쓰기 알림과 구별해야 합니다.'), ('접근 알림을 호출한 것만으로 실제 잠금을 얻을까요?', ['아니요. 뒤의 arch 함수가 실제 연산을 해요', '네. 알림 하나가 실제 잠금까지 대신해요'], '감싼 함수는 분석 정보를 알린 뒤 arch_test_and_set_bit_lock을 호출합니다. 관찰자에게 작업을 알리는 단계와 실제 작업 단계는 서로 다릅니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_341.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
